#!/usr/bin/env python3
"""Repair an already-built unsigned .ipa for sideloading (no Mac / no rebuild).

A CMake/Xcode build made with CODE_SIGNING_ALLOWED=NO produces a very "naked"
.app: just the Mach-O, Info.plist and PkgInfo. Some on-device signers (ESign)
sign that happily, but iOS installd can reject it with a generic
"Unable to Install". This script fixes the bundle in place by:

  * adding real RGB app icons (ios/icons/*.png, generated by make_icons.py);
  * adding CFBundleIcons / CFBundlePrimaryIcon to Info.plist;
  * removing UIRequiredDeviceCapabilities (a capability mismatch after
    third-party re-signing is a silent install refusal);
  * adding ITSAppUsesNonExemptEncryption = false;
  * optionally replacing the placeholder bundle identifier;
  * repacking a clean Payload/*.app IPA without __MACOSX / AppleDouble junk.

The .ipa is still UNSIGNED - sign it afterwards with ESign / Sideloadly.

Usage:
    python3 patch_ipa.py INPUT.ipa OUTPUT.ipa [--bundle-id com.foo.bar]
"""
import argparse
import os
import plistlib
import sys
import zipfile

HERE = os.path.dirname(os.path.abspath(__file__))
ICON_DIR = os.path.join(HERE, "icons")
ICON_BASENAMES = ("Icon-60@2x", "Icon-60@3x", "Icon-1024")


def find_app(names):
    apps = sorted({n.split("/")[1] for n in names
                   if n.startswith("Payload/") and n.count("/") >= 2
                   and n.split("/")[1].endswith(".app")})
    if len(apps) != 1:
        raise SystemExit(f"expected exactly one Payload/*.app, found: {apps}")
    return "Payload/" + apps[0] + "/"


def patch_plist(raw, bundle_id):
    fmt = plistlib.FMT_BINARY if raw[:8] == b"bplist00" else plistlib.FMT_XML
    pl = plistlib.loads(raw)
    if bundle_id:
        pl["CFBundleIdentifier"] = bundle_id
    pl["CFBundleIcons"] = {
        "CFBundlePrimaryIcon": {
            "CFBundleIconFiles": list(ICON_BASENAMES),
            "UIPrerenderedIcon": True,
        }
    }
    pl.pop("UIRequiredDeviceCapabilities", None)
    pl.pop("UISupportedDevices", None)
    pl["ITSAppUsesNonExemptEncryption"] = False
    return plistlib.dumps(pl, fmt=plistlib.FMT_XML), pl


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("input")
    ap.add_argument("output")
    ap.add_argument("--bundle-id", default="com.maksim.imguioverlay")
    args = ap.parse_args()

    for name in ICON_BASENAMES:
        path = os.path.join(ICON_DIR, name + ".png")
        if not os.path.isfile(path):
            raise SystemExit(f"missing icon {path} - run: python3 make_icons.py")

    with zipfile.ZipFile(args.input) as src:
        names = src.namelist()
        app = find_app(names)
        entries = {}
        order = []
        for n in names:
            if n.startswith("__MACOSX/") or "/._" in n or n.endswith("/"):
                continue
            entries[n] = src.read(n)
            order.append(n)

        if app + "Info.plist" not in entries:
            raise SystemExit("Info.plist not found in " + app)
        entries[app + "Info.plist"], pl = patch_plist(
            entries[app + "Info.plist"], args.bundle_id)

        for base in ICON_BASENAMES:
            with open(os.path.join(ICON_DIR, base + ".png"), "rb") as f:
                entries[app + base + ".png"] = f.read()

    out_dirs = ["Payload/", app]
    icon_names = [app + b + ".png" for b in ICON_BASENAMES]
    ordered = [n for n in order if n not in icon_names] + icon_names

    with zipfile.ZipFile(args.output, "w", zipfile.ZIP_DEFLATED) as dst:
        for d in out_dirs:
            dst.writestr(zipfile.ZipInfo(d), b"")
        for n in ordered:
            dst.writestr(n, entries[n])

    print(f"wrote {args.output} ({os.path.getsize(args.output):,} bytes)")
    print(f"bundle-id      : {pl.get('CFBundleIdentifier')}")
    print(f"icons          : {', '.join(ICON_BASENAMES)}")
    print(f"capabilities   : {pl.get('UIRequiredDeviceCapabilities', 'REMOVED')}")
    print("signature      : still UNSIGNED - sign with ESign / Sideloadly")


if __name__ == "__main__":
    main()
